steps.content:
// session.rs:836 — 会话初始化后立即启动后台任务
memories::start_memories_startup_task(
  &sess,
  Arc::clone(&config),
  &session_configuration.session_source,
);

// start.rs:19 — 三个跳过条件：
if config.ephemeral
    || !config.features.enabled(Feature::MemoryTool)  // key="memories"
    || matches!(source, SessionSource::SubAgent(_))
{
    return; // 跳过：临时会话 / 未启用 / SubAgent
}
if session.services.state_db.is_none() {
    warn!("state db unavailable; skipping");
    return; // 跳过：需要 Feature::Sqlite
}

// 后台异步任务（不阻塞主会话）：
tokio::spawn(async move {
    phase1::prune(&session, &config).await;  // 清理过期 stage1_outputs
    phase1::run(&session, &config).await;    // Phase1 提取
    phase2::run(&session, config).await;     // Phase2 整合
});

// phase1.rs:196 — claim_startup_jobs()
// 扫描 SQLite threads 表，争抢 Stage1 jobs
state_db.claim_stage1_jobs_for_startup(
    session.conversation_id,  // 排除自身
    Stage1StartupClaimParams {
        scan_limit:             5_000,
        max_claimed:            16,   // max_rollouts_per_startup
        max_age_days:           30,   // max_rollout_age_days
        min_rollout_idle_hours: 6,    // 闲置 ≥6h
        allowed_sources:        INTERACTIVE_SESSION_SOURCES,
        lease_seconds:          3_600,
    },
).await

// SQL 条件（简化）：
// WHERE memory_mode = 'enabled'
//   AND id != current_session_id
//   AND updated_at_ms >= (now - 30days)
//   AND updated_at_ms <= (now - 6hours)   -- 闲置
//   AND stage1_outputs.source_updated_at < threads.updated_at  -- 过期
// ORDER BY updated_at_ms DESC
// LIMIT 5000

// 返回：≤16 个 Stage1JobClaim { thread, ownership_token }

// phase1.rs:312 — job::sample() — 每个 job 并发执行（上限 8）

// Step 1: 加载 rollout .jsonl
let (rollout_items, _, _) =
    RolloutRecorder::load_rollout_items(&thread.rollout_path).await?;

// Step 2: 过滤 rollout 内容
// - 去掉 developer role 消息（系统指令）
// - 去掉 memory-excluded contextual 片段
// - 保留 user/assistant/tool 消息
let rollout_contents =
    serialize_filtered_rollout_response_items(&rollout_items)?;
// 注意：内容经过 redact_secrets() 脱敏处理

// Step 3: 构建用户消息（截断）
// stage_one_input.md 模板：
// "Analyze this rollout and produce JSON with
//  raw_memory, rollout_summary, rollout_slug."
// rollout_path: /home/user/.codex/rollouts/xxx.jsonl
// rollout_cwd: /workspace/auth
// rollout_contents: [截断到 70% context window]
let msg = build_stage_one_input_message(
    &model_info, &thread.rollout_path,
    &thread.cwd, &rollout_contents)?;
// rollout_token_limit = model.context_window
//   * effective_context_window_percent / 100
//   * CONTEXT_WINDOW_PERCENT(70) / 100
// 兜底: DEFAULT_STAGE_ONE_ROLLOUT_TOKEN_LIMIT = 150_000

// phase1.rs — 调用模型
let prompt = Prompt {
    input: vec![ResponseItem::Message { role: "user", content: [msg], .. }],
    tools: vec![],  // 无工具！纯文本提取
    base_instructions: BaseInstructions {
        text: phase_one::PROMPT.to_string(),  // stage_one_system.md
    },
    output_schema: Some(json!({
        "type": "object",
        "properties": {
            "rollout_summary": { "type": "string" },
            "rollout_slug":    { "type": ["string", "null"] },
            "raw_memory":      { "type": "string" }
        },
        "required": ["rollout_summary", "rollout_slug", "raw_memory"],
        "additionalProperties": false
    })),
    ..
};
// 模型: gpt-5.4-mini, ReasoningEffort::Low
// 流式消费 SSE，提取最终 JSON 文本

// 脱敏处理：
output.raw_memory = redact_secrets(output.raw_memory);
output.rollout_summary = redact_secrets(output.rollout_summary);
output.rollout_slug = output.rollout_slug.map(redact_secrets);

// NO-OP 检测：
if output.raw_memory.is_empty() || output.rollout_summary.is_empty() {
    // 标记成功但无输出
    state_db.mark_stage1_job_succeeded_no_output(...).await?;
    return JobOutcome::SucceededNoOutput;
}

// phase1.rs — result::success() — 持久化成功结果
state_db.mark_stage1_job_succeeded(
    thread.id,
    &claim.ownership_token,
    thread.updated_at.timestamp(),
    &output.raw_memory,
    &output.rollout_summary,
    output.rollout_slug.as_deref(),
).await?
// 内部 SQL（简化）：
// 1. UPDATE jobs SET status='done', last_success_watermark=input_watermark
//    WHERE kind='memory_stage1' AND job_key=thread_id AND ownership_token=?
// 2. INSERT INTO stage1_outputs (...) ON CONFLICT(thread_id) DO UPDATE
//    WHERE excluded.source_updated_at >= stage1_outputs.source_updated_at
// 3. enqueue_global_consolidation(source_updated_at)
//    → UPSERT jobs SET kind='memory_consolidate_global', job_key='global'
//      input_watermark = MAX(current, new)

// stage1_outputs 表结构：
// thread_id, rollout_path, source_updated_at,
// raw_memory, rollout_summary, rollout_slug, generated_at,
// selected_for_phase2, selected_for_phase2_source_updated_at,
// usage_count, last_usage

// phase2.rs:46 — run() — 全局整合流程

// Step 1: 争抢全局单例 job
state_db.try_claim_global_phase2_job(
    session.conversation_id,
    JOB_LEASE_SECONDS,  // 3_600s
).await?
// Claimed { ownership_token, input_watermark } → 继续
// SkippedNotDirty → input_watermark <= last_success_watermark
// SkippedRunning  → 另一 worker 持有有效 lease

// Step 2: 构建 SubAgent 配置
// agent_config.cwd = ~/.codex/memories/
// agent_config.memories.generate_memories = false  // 禁递归
// agent_config.permissions.approval_policy = Never
// Feature::SpawnCsv / Collab / MemoryTool 全部 disable
// sandbox: WorkspaceWrite { writable_roots: [codex_home], network_access: false }
// model: gpt-5.4, reasoning_effort: Medium

// Step 3: 查询 Phase2 输入
let selection = state_db.get_phase2_input_selection(
    max_raw_memories,  // default 256
    max_unused_days,   // default 30
).await?
// 返回: { selected, previous_selected, retained_thread_ids, removed }

// phase2.rs — 同步 FS + Spawn Agent

// Step 4: 同步文件系统（在 spawn 之前）
sync_rollout_summaries_from_memories(
    &root, &artifact_memories, max_raw_memories).await?;
// → 写入/删除 ~/.codex/memories/rollout_summaries/*.md
// 文件名: {YYYY-MM-DDTHH-MM-SS}-{4char-base62-hash}[-slug].md
// 例: 2026-05-29T10-30-00-3aB9-auth_module_refactor.md

rebuild_raw_memories_file_from_memories(
    &root, &artifact_memories, max_raw_memories).await?;
// → 重写 ~/.codex/memories/raw_memories.md
// 格式: ## Thread `{thread_id}`\nupdated_at: ...\ncwd: ...\n{raw_memory}

// Step 5: 构建 consolidation prompt
// consolidation.md (835行) 渲染：
//   {{ memory_root }} = ~/.codex/memories/
//   {{ phase2_input_selection }} = diff 文本
//   {{ memory_extensions_folder_structure }} = 如果有 extensions

// Step 6: Spawn SubAgent
let thread_id = session.services.agent_control
    .spawn_agent(agent_config, prompt.into(),
        Some(SessionSource::SubAgent(
            SubAgentSource::MemoryConsolidation))).await?;

// Step 7: Heartbeat 循环（tokio::spawn 异步）
// 每 90s 调用 state_db.heartbeat_global_phase2_job()
// → UPDATE jobs SET lease_until = now + 3600
// 若 heartbeat 失败 → Errored

// core/src/codex.rs:2366 — 每个 turn 注入 developer instructions
if turn_context.features.enabled(Feature::MemoryTool)
    && turn_context.config.memories.use_memories  // default true
    && let Some(memory_prompt) =
        build_memory_tool_developer_instructions(
            &turn_context.config.codex_home).await
{
    developer_sections.push(memory_prompt);
}

// prompts.rs:265 — build_memory_tool_developer_instructions()
// 1. 读取 ~/.codex/memories/memory_summary.md
// 2. 截断到 5_000 tokens
// 3. 渲染 read_path.md 模板：
//    - memory 文件布局说明
//    - Quick Memory Pass 协议（≤4-6 步）
//    - 如何判断是否需要查记忆
//    - drift 验证决策树
//    - Memory Citation 格式要求
//    - === MEMORY_SUMMARY BEGINS ===
//    - {{ memory_summary }} 内容
//    - === MEMORY_SUMMARY ENDS ===

// 条件：memory_summary.md 存在且非空才注入
// 每轮重新构建（per-turn），Phase2 更新后立即生效
